changeSet.sql:
CREATE OR ALTER TRIGGER trg_student_attempt_quiz_denorm ON student_attempt AFTER INSERT, DELETE AS BEGIN DECLARE @AffectedQuizzes TABLE (quiz_id BIGINT);
INSERT INTO @AffectedQuizzes (quiz_id) SELECT DISTINCT tq.quiz_id FROM inserted i INNER JOIN task_quiz tq ON i.task_id = tq.task_id UNION SELECT DISTINCT tq.quiz_id FROM deleted d INNER JOIN task_quiz tq ON d.task_id = tq.task_id;
UPDATE q SET q.total_attempts = ( SELECT COUNT(DISTINCT sa.id) FROM task_quiz tq INNER JOIN student_attempt sa ON sa.task_id = tq.task_id WHERE tq.quiz_id = q.id ) FROM quiz q INNER JOIN @AffectedQuizzes aq ON q.id = aq.quiz_id; END;
